#include "app.h"
void App::hit(D2D1_RECT_F r,std::string a,std::string d,int i,std::wstring tip){hits.push_back({r,std::move(a),std::move(d),i,std::move(tip)});}
void App::button(D2D1_RECT_F r,Icon i,std::string a,std::wstring tip,unsigned c,std::string d){if(hover==(int)hits.size())paint.round(r,theme.hover);paint.icon(i,r.left+(width(r)-17)/2,r.top+(height(r)-17)/2,17,c?c:theme.muted);hit(r,std::move(a),std::move(d),0,std::move(tip));}
void App::textButton(std::wstring s,D2D1_RECT_F r,std::string a,std::string d,unsigned c,float size){if(hover==(int)hits.size())paint.round(r,theme.hover);paint.text(s,r,c?c:theme.text,size,400,2);hit(r,std::move(a),std::move(d));}
void App::fileGlyph(Paint&p,const std::string&path,float x,float y,float size){auto e=extension(path);if(e=="py")p.text(L"Py",rect(x,y,18,size+5),theme.blue,size-1,500,0,true);else if(e=="md"){p.outline(rect(x,y+4,15,11),theme.muted,1);p.text(L"M↓",rect(x+1,y,15,size+7),theme.muted,8,600,0,true);}else if(e=="toml"||e=="json")p.text(L"{ }",rect(x,y,18,size+5),0xb9a16e,10,500,0,true);else if(e=="js")p.text(L"JS",rect(x,y,18,size+5),0xd9c07c,10,500,0,true);else p.icon(Icon::File,x,y+2,15,theme.muted);}
